-- Versions anglaises du contenu (28 projets et les categories de competences).
-- A executer une fois dans l'editeur SQL de Supabase, apres migrate-projets-reels.sql. Le script peut etre relance
-- sans risque : il ne remplit que les champs anglais encore vides, un texte modifie depuis l'admin est conserve.
-- Un champ anglais vide affiche le texte francais sur la version anglaise du site.

BEGIN;

-- L'API cree aussi ces colonnes au demarrage : elles sont reprises ici pour que le script suffise seul.
ALTER TABLE projects
  ADD COLUMN IF NOT EXISTS title_en VARCHAR(255),
  ADD COLUMN IF NOT EXISTS short_description_en TEXT,
  ADD COLUMN IF NOT EXISTS full_description_en TEXT,
  ADD COLUMN IF NOT EXISTS context_en TEXT,
  ADD COLUMN IF NOT EXISTS approach_en TEXT,
  ADD COLUMN IF NOT EXISTS results_en TEXT,
  ADD COLUMN IF NOT EXISTS challenges_en TEXT;
ALTER TABLE blog_posts
  ADD COLUMN IF NOT EXISTS title_en VARCHAR(255),
  ADD COLUMN IF NOT EXISTS excerpt_en TEXT,
  ADD COLUMN IF NOT EXISTS content_en TEXT;
ALTER TABLE profile ADD COLUMN IF NOT EXISTS bio_en TEXT;
ALTER TABLE skill_categories ADD COLUMN IF NOT EXISTS name_en VARCHAR(255);
ALTER TABLE cv_sections ADD COLUMN IF NOT EXISTS title_en VARCHAR(255);
ALTER TABLE cv_items
  ADD COLUMN IF NOT EXISTS title_en VARCHAR(255),
  ADD COLUMN IF NOT EXISTS subtitle_en VARCHAR(255),
  ADD COLUMN IF NOT EXISTS description_en TEXT,
  ADD COLUMN IF NOT EXISTS highlights_en JSONB;

UPDATE projects SET
  title_en = COALESCE(NULLIF(projects.title_en, ''), t.title_en),
  short_description_en = COALESCE(NULLIF(projects.short_description_en, ''), t.short_description_en),
  full_description_en = COALESCE(NULLIF(projects.full_description_en, ''), t.full_description_en),
  context_en = COALESCE(NULLIF(projects.context_en, ''), t.context_en),
  approach_en = COALESCE(NULLIF(projects.approach_en, ''), t.approach_en),
  results_en = COALESCE(NULLIF(projects.results_en, ''), t.results_en),
  challenges_en = COALESCE(NULLIF(projects.challenges_en, ''), t.challenges_en)
FROM (VALUES
  ('watertracker-afrique', 'WaterTracker Africa: monitoring water reservoirs by satellite', 'Monthly monitoring of 96 water reservoirs around Ouagadougou from satellite imagery, with a 1-3 month forecast of how full they will be.', 'Every month, a pipeline measures the water surface of 96 reservoirs from Sentinel-2 and Sentinel-1, forecasts their fill rate 1 to 3 months ahead with a confidence interval, and publishes a risk bulletin on an interactive map.', 'Around Ouagadougou, small reservoirs keep farming and livestock going, but they dry up during the dry season. Field measurements are rare: the reservoirs need regular monitoring and a warning before the level becomes critical.', 'Automated collection with Google Earth Engine (10 m Sentinel-2 fused with Sentinel-1 radar, CHIRPS rainfall, ERA5-Land climate), storage in PostgreSQL/PostGIS, scikit-learn models validated over time with an 80% interval (quantile loss), Prophet to estimate when a reservoir will run dry, and recommendations written by an LLM. The FastAPI API is scheduled with APScheduler; the React interface shows a Leaflet map.', 'A monthly bulletin ranks the 96 reservoirs by risk level, with the measured fill rate, the 1-3 month forecast, the probability of reaching the critical level and a CSV export. The research notebook and the production collector give identical values: the pipeline is reproducible.', 'Rainy-season clouds break the optical series: fusing it with Sentinel-1 radar produced a continuous monthly series. A forecast without uncertainty can''t be acted on, so each prediction comes with its interval and is compared with a baseline forecast (skill score).'),
  ('maintenance-predictive-kafka', 'Streaming predictive maintenance (NASA C-MAPSS)', 'Predicts the remaining useful life of jet engines, served in real time by a Kafka pipeline that publishes a maintenance decision.', 'At every cycle, a regression model estimates how many cycles an engine has left before failure, from 26 sensor readings. A Kafka pipeline ingests the readings, computes the time-based features and publishes a decision: normal, inspection, closer monitoring or immediate intervention.', 'Repairing an engine after it fails costs far more than planning the intervention. NASA''s C-MAPSS dataset simulates jet engines degrading until they fail.', 'Cleaning and creation of 155 causal time-based features, split by engine (GroupShuffleSplit) so that no engine is seen in both training and validation, and comparison of several models. In production, a Kafka producer sends the readings; a consumer keeps each engine''s history, predicts, and publishes the decision on an output topic.', 'Random Forest selected: a mean error of 8.4 cycles (RMSE 11.7) on engines never seen in training. Each prediction becomes a business decision based on thresholds (20 cycles or fewer: immediate intervention).', 'NASA''s official score penalises overestimating the remaining life far more than underestimating it, because overestimating delays the intervention: the decision thresholds follow that asymmetry. The features had to stay causal so that streaming gives the same result as the notebook.'),
  ('undp-sdg-classifier', 'Classifying UNDP projects against the 17 SDGs', 'AI platform that analyses reports (PDF, DOCX, TXT) and classifies them against the 17 Sustainable Development Goals.', 'A multilingual XLM-RoBERTa model, fine-tuned for multi-label classification, gives each document a score for each of the 17 SDGs, along with the passages that support it. A conversational assistant then answers questions using only the analysed documents.', 'UNDP teams produce many project reports. Linking each one to the Sustainable Development Goals it serves is done by hand and takes time.', 'Fine-tuned XLM-RoBERTa model (17 sigmoid outputs: a document can touch several SDGs, with three confidence levels), FastAPI API with SQLite history, Pinecone vector search (all-MiniLM-L6-v2 embeddings) and Gemini for a chat grounded in the corpus, and a Next.js 15 interface with a dashboard.', 'A complete application: analysis of a document with its main SDG, supporting passages, key figures and a summary; documents ranked by goal; SDG distribution in a dashboard; and a chat that cites its sources.', 'Handling documents written in several languages, hence the choice of XLM-RoBERTa, and limiting what the chat makes up by requiring it to answer only from the passages it is given.'),
  ('ai-insurance-operations', 'AI Insurance: AI-assisted claims processing', 'Platform that automates the intake, triage and risk analysis of insurance claims, with human review of sensitive cases.', 'An LLM extracts the information from a free-text claim, an agent asks for anything missing, a rules engine assigns an explainable risk score from 0 to 100, and risky files must go through human review.', 'At an insurance company, every claim arrives as free text and has to be read, completed and assessed before a decision: slow, repetitive work.', 'Asynchronous FastAPI backend (SQLAlchemy) organised into services: extraction by GPT-4o-mini with structured outputs, a follow-up agent, a risk engine with explainable signals, statistics and an audit log, on a PostgreSQL database (Supabase). Next.js 14 interface (ai-insurance-frontend repo): customer form, processing queue, case file and indicators.', 'A complete chain from claim to decision: automatic extraction, a justified risk score, mandatory human review for risky cases, traceability of every action, and a dashboard of time saved and automation rate.', 'Keeping a human in the loop without slowing down simple cases, and making every score understandable to a claims handler by showing the signals behind it rather than an opaque number.'),
  ('ai-sql-assistant', 'AI SQL Assistant: querying a database in plain language', 'You ask a question in plain language; the assistant writes the SQL, runs it read-only and answers clearly.', 'The LLM receives the database schema and writes the SQL query, which is validated and then run read-only. It then interprets the result and answers in natural language, streamed.', 'Business teams have questions about their data but don''t speak SQL: they depend on an analyst for every figure.', 'FastAPI and LangChain backend, query validation (SELECT and WITH only), a demo SQLite database and streamed answers (SSE). The LLM is a choice: Ollama locally (free and private) or NVIDIA NIM for 70-billion-parameter models. Next.js interface with conversation history.', 'An assistant anyone can use without knowing SQL: it answers with the right figures, refuses any write to the database and can run entirely offline.', 'Stopping an LLM from modifying the database, through strict validation before execution, and getting reliable SQL from a small local model.'),
  ('smecofarm-edge-ai', 'SmEcoFarm: a smart farm on a Raspberry Pi (Edge AI)', 'A Raspberry Pi uses computer vision to spot birds and tomato diseases, monitors the storehouse and raises fire alerts, with no internet.', 'A school prototype where a single Raspberry Pi 4 runs two stations. In the field: bird detection, with a buzzer to scare them off, and diagnosis of 10 tomato diseases. In the storehouse: crop storage and fire safety. The models run on the device, with no connection.', 'Small farms lose part of their harvest to birds, diseases and poor storage, without the means for round-the-clock monitoring.', 'Embedded TensorFlow Lite models (EfficientDet-Lite0 for birds, MobileNetV2 for diseases), colour-based flame detection, DHT11 and MQ-135 sensors, a relay-driven fan with hysteresis, a Blynk dashboard, Gmail alerts with a photo, and automatic start at boot.', 'An eagle detected at 84% confidence, with no false alarm on 6 photos without birds. The business logic can be tested without hardware thanks to 27 automated tests.', 'Running several vision models on a Raspberry Pi and working within the hardware''s limits: the DHT11 can''t measure above 80% humidity, so the ''humidity too high'' rule is ready but switched off.'),
  ('gaalbrain-evaluation-socratique', 'GaAlBrain: assessing understanding through Socratic questioning', 'An LLM asks Socratic questions about a concept to measure what a student has really understood, with tracking for the teacher.', 'Instead of a multiple-choice test, the student talks with an AI that questions them the way Socrates would. Each session produces scores per concept, an integrity score and a report; the teacher follows the class from a dashboard.', 'A multiple-choice test measures real understanding poorly and is easy to game, but a teacher doesn''t have time to question every student orally.', 'TypeScript Express backend with the Groq SDK to generate the questions, and a local fallback if generation fails. Sessions, scores per concept, reports and import of course material; React interface (TanStack) with a student area and a teacher area.', 'An MVP with assessment sessions, how understanding of each concept evolves, a 30-day integrity score and a student-by-student view for the teacher.', 'Getting usable questions from the LLM in a stable format: extracting and normalising the returned JSON, with an automatic fallback when the answer can''t be used.'),
  ('fake-news-detection-nlp', 'Fake news detection with NLP', 'Classifies articles as real or fake with natural language processing, alongside a topic analysis (LDA).', 'Comparison of text representations (bag of words, TF-IDF) and classifiers (logistic regression, Naive Bayes, linear SVM) on the Kaggle Fake and Real News dataset, followed by topic modelling with LDA.', 'False information spreads faster than it can be checked. A first automatic filter helps decide which content to check first.', 'Merging the Fake and True datasets, text preprocessing with NLTK (lowercase, punctuation, stop words), BoW and TF-IDF representations, training and comparing three classifiers, then LDA to understand the dominant topics.', '99% accuracy on 8,837 test articles with logistic regression and SVM, against 93% for Naive Bayes.', 'Such a high score calls for caution: the model may rely on each source''s style in the dataset rather than on the content, which limits how well it generalises.'),
  ('fraud-detection-kafka', 'Real-time bank fraud detection with Kafka', 'Transactions flow through Kafka; a Java consumer calls a machine learning API that returns a fraud or legitimate decision.', 'A Python producer sends transactions to Kafka, a Java consumer reads them and calls a FastAPI API serving a Random Forest model. The API returns the fraud probability and the decision.', 'Fraud has to be stopped at the moment of the transaction, not during a later check. Fraud is very rare: 492 out of 284,807 transactions (0.17%) in the Kaggle dataset used.', 'Exploration and training of a Random Forest (scikit-learn), choice of the decision threshold by comparing precision and recall, serving the model through FastAPI, and a Kafka pipeline with a Python producer and a Java 21 consumer (Maven).', 'At the chosen threshold of 0.40: precision of 0.88, recall of 0.83 and F1 of 0.85 on the fraud class. The pipeline processes transactions continuously.', 'With 0.17% fraud, accuracy means nothing: a model that detects nothing scores 99.8%. The threshold was therefore chosen on the trade-off between precision and recall for the rare class.'),
  ('africa-kpis-dashboard', 'Africa Dev Data Mart: African development indicators', 'Pipeline that extracts World Bank indicators for 54 African countries (2000-2024), structures them in DuckDB and serves them in a dashboard.', 'A reproducible pipeline extracts, cleans and loads ten development indicators (GDP, access to water and electricity, school enrolment, child mortality, poverty…) for every African country into a DuckDB data mart, which then feeds a web dashboard for decision-makers.', 'Development indicators exist, but they are scattered and hard to compare from one country to another. A decision-maker needs a clean, comparable view.', 'Extraction from the World Bank v2 API with caching, a reference list of African countries (regional aggregates excluded), transformation and cleaning in Python, loading into DuckDB, Plotly charts, JSON export to a static Next.js dashboard, and methodology documentation.', 'A data mart covering 54 countries over 25 years, and a dashboard with an indicator grid, multi-country line charts, a choropleth map and a two-indicator comparison.', 'Handling missing values and incomplete series across countries and years, while keeping the pipeline reproducible end to end.'),
  ('ftth-prediction-togo', 'Predicting access to fibre broadband in Togo', 'Model that predicts Togolese households'' potential access to fibre (FTTH) from socio-demographic and geospatial data.', 'From 30,558 households and 46 variables, the model estimates each household''s probability of fibre access and brings out the drivers of connectivity, to guide where the infrastructure is rolled out.', 'Project carried out for the ACDS 2025 challenge: identifying priority households and areas for the fibre roll-out in Togo.', 'Exploratory analysis, preparation of 46 variables (housing, equipment, geospatial features), comparison of several models including Random Forest and XGBoost, evaluation on AUC, F1, precision and recall, then export of the best model and its predictions.', 'Random Forest selected: an AUC of 0.88 and an F1 of 0.84 on the test set, with a recall of 0.91, so few eligible households are missed.', 'Processing a 2.2 GB dataset on a personal computer, and watching the gap between training (AUC 0.98) and test (0.88) to limit overfitting.'),
  ('ml-portfolio-projets', 'A collection of 10 machine learning projects', 'Ten documented projects: NLP, deep learning, time series, regression, semantic search and LLMs.', 'An organised repository covering the full machine learning cycle across ten cases: fake news detection, churn with TensorFlow, dimensionality reduction with PCA, ARIMA/GARCH stock forecasting, semantic search with Pinecone, text generation with LLMs and regression in R.', 'Bringing together short, documented projects that show a command of the core machine learning techniques.', 'One documented notebook per project, a shared structure, a reproducible environment and continuous integration with GitHub Actions.', '10 projects ready to be read or reused, including fake news detection at 99.3% accuracy and weighted semantic search with Sentence Transformers and Pinecone.', 'Keeping the documentation consistent and the projects reproducible despite very different domains and libraries.'),
  ('music-genre-classification-pca', 'Music genre classification with PCA', 'Dimensionality reduction with PCA, then logistic regression to predict the genre of tracks that have none.', 'On 1,000 tracks described by numerical features, PCA reduces the dimension while keeping at least 80% of the variance, then a logistic regression predicts the genre of unlabelled tracks.', 'Some tracks in the dataset have no genre: it has to be predicted from their audio features.', 'Exploration and correlation analysis, standardisation, PCA (at least 80% of the variance kept), and logistic regression with and without PCA to measure what the dimensionality reduction brings.', 'A complete pipeline that assigns a genre to unlabelled tracks and compares performance with and without PCA.', 'Choosing the number of components: enough to keep the information, few enough to reduce noise and collinearity.'),
  ('simulation-pont-marin', 'Mechanical simulation of an offshore bridge', 'Streamlit app that computes and shows in 3D the stresses on an offshore bridge exposed to wind, waves and earthquakes.', 'You set the bridge geometry (deck, piers) and the hazards (wind, water depth, seismic acceleration); the app computes the forces using continuum mechanics and displays the structure in 3D.', 'A continuum mechanics project: making the effects of environmental loads on an offshore structure visible.', 'Streamlit app with sidebar controls, physics calculations with NumPy (Young''s modulus, concrete and seawater densities, yield strength) and interactive 3D rendering with Plotly.', 'An interactive tool that shows live how each parameter changes the stresses and the risk of exceeding the material''s limit.', 'Turning mechanics formulas into a calculation model that is simple, fast and readable on screen.'),
  ('dataviz-energie-afrique', 'DataViz: electricity production by country', 'Electricity production data collected by web scraping, cleaned in Python and analysed in a Power BI dashboard.', 'A scraping script collects the electricity production data published by Our World in Data, a notebook cleans and prepares it, and a Power BI dashboard analyses production by country and by source.', 'Project carried out at Centrale Casablanca: analysing electricity production by country and by source from public data.', 'A reusable scraping module (Selenium, Helium, BeautifulSoup) called from a notebook, cleaning with pandas and Excel export, then modelling and visualisation in Power BI.', 'A clean dataset and an interactive Power BI dashboard on electricity production.', 'Turning a dynamic web table into a dataset that is usable and consistent from one country to another.'),
  ('innopro-gestion-maintenance', 'InnoFaso: maintenance and production management', 'Business web app to manage maintenance forms, production, stock and alerts, with AI-generated forms.', 'A fullstack application built as a pair: drag-and-drop configurable forms, a submission and approval workflow, raw material stock, automatic alerts and Excel exports, with form generation assisted by an LLM.', 'A production unit tracked its maintenance and production on paper and in spreadsheets, with no alert for a critical breakdown or low stock.', 'Node.js/Express API and PostgreSQL (13 migrations), JWT authentication with a refresh token, a form builder (text, number, date, signature, photo…), reversible deletion, Excel export (ExcelJS) and form generation through Groq (Llama 3.3 70B). React, Vite and Tailwind interface.', 'Two working modules, maintenance and production: form submission and approval, filterable history, alerts (overdue form, low stock, critical breakdown) and Excel exports.', 'Making the forms fully configurable without redeploying the application, and merging two developers'' work on the same codebase.'),
  ('cap-assistant-planification', 'Cap: a day-planning assistant', 'Installable web app that helps plan a realistic day and move towards your goals. In development.', 'A Next.js app you can install on your phone (PWA): sign-in with a code sent by email, goals, a daily plan split into blocks, reviews and notifications, on a Supabase database protected by tested security rules.', 'Overly ambitious to-do lists are discouraging. The idea: plan a doable day and track what actually moves forward.', 'Next.js (App Router) and TypeScript, Supabase (PostgreSQL, one-time code sign-in, row-level security), versioned migrations, a service worker and push notifications, Vitest unit tests, Playwright end-to-end tests and GitHub Actions continuous integration.', 'The foundation is in place: authentication, the data model (goals, plans, blocks, reviews, lessons), tested security rules and a continuous integration pipeline.', 'Testing security directly in the database, with tests dedicated to the access rules, and not only through the interface.'),
  ('plateforme-edtech', 'EdTech platform: courses, quizzes and AI assistant API', 'API for a learning platform for students in French-speaking Africa: courses, resources, progressive quizzes and an AI assistant.', 'The backend of an EdTech SaaS designed for mobile and slow networks: course tracking, related resources, quizzes that get progressively harder, an AI assistant that answers in the context of the course, and progress tracking.', 'Students in French-speaking Africa often study on their phones, with an unstable connection, and lack support between classes.', 'TypeScript Express API; Supabase for the PostgreSQL database, authentication and row-level security; course, resource, quiz, AI assistant and progress modules; documented endpoints.', 'A documented API covering every module, with access control enforced directly in the database.', 'Designing a lightweight API for slow networks and protecting each student''s data at the database level.'),
  ('agblenuku-approvisionnement-agricole', 'Agblenuku: a farm supply platform', 'API that connects local farmers with the city''s restaurants, hotels and shops.', 'The backend of a platform where a restaurant states a need, finds available farmers, places an order and tracks its supply. The architecture is designed to add recommendations, demand forecasting and logistics optimisation later.', 'Local farmers struggle to sell directly to city businesses, which themselves have little visibility on what is available.', 'Modular NestJS REST API in TypeScript, PostgreSQL with Prisma, JWT authentication and roles (farmer, business customer, administrator), images on Supabase Storage, input validation and Swagger documentation.', 'A backend MVP: farmer profiles, product catalogue, orders and tracking, with a documented API.', 'Laying down, from the MVP, a data model clean enough to add the AI features later without starting over.'),
  ('campusfix', 'CampusFix: reporting breakdowns on a campus', 'Platform to report a breakdown on campus with a QR code and follow it through to the repair.', 'Students and staff report a problem (room, equipment) by scanning a QR code; the managers track, assign and close the requests from a dashboard.', 'On a campus, breakdowns are reported verbally or by email: they get lost and nobody follows them up.', 'TypeScript Express API (authentication, locations, reports, log, manager area) and a Next.js interface with QR code generation and charts.', 'A complete workflow, from report to resolution, with history and an overview for the managers.', 'Making reporting simple enough to be done in a few seconds from a phone.'),
  ('portfolio-kwami-dev', 'This portfolio (kwami.dev)', 'Fullstack site with an admin area: projects, blog, PDF resume and contact messages.', 'The site you are reading: a React interface that reads an Express API, with an admin area to edit projects, articles, skills and profile without touching the code.', 'A static portfolio quickly goes out of date; the content had to be updatable in a few clicks.', 'React, TypeScript, Vite and Tailwind interface deployed on Vercel; Express API (portfoliobackend repo) deployed on Render with PostgreSQL (Supabase); admin protected by JWT; resume generated as a PDF; contact form with email notification.', 'A site that can be managed end to end, hardened for security: login attempt limits, content escaping and spam protection.', 'Keeping a single space for visitors and the admin without exposing editing features to visitors.'),
  ('gestion-2ie', 'Gestion 2iE: a school management app', 'Web app to manage a school''s resources, with authentication.', 'A React and Express app for signing in and managing a school''s resources: create, view, edit and delete.', 'A course project to build a complete web architecture, from the interface to the API.', 'React, Vite and Tailwind interface; Express API with authentication and resource routes, and separate models.', 'An app that works end to end: sign-in and resource management.', 'Structuring the API cleanly (routes and models) and handling authentication between the interface and the server.'),
  ('blog-api-rest', 'Blog REST API (Node.js, MySQL, JWT)', 'Backend for a blog: articles, users and JWT authentication, with a layered architecture.', 'A REST API organised into routes, controllers, models and middleware, with JWT authentication, hashed passwords, security headers and a file of endpoint tests.', 'A course project: designing a well-structured backend for a blog application.', 'Node.js and Express, MySQL through mysql2, JWT, bcrypt, Helmet and CORS, a versioned SQL schema and test requests in REST Client format.', 'A complete API to manage articles and users, ready to connect to an interface.', 'Clearly separating responsibilities (routes, business logic, data access) to keep the code readable and testable.'),
  ('blogmag', 'BlogMag: an online magazine', 'Magazine-style blog in Next.js, with article pages, article creation and documented UX choices.', 'An online magazine with an editorial home page, a carousel, article pages and a creation form, along with a document that explains the UX choices.', 'A course project focused on the user experience of an online publication.', 'Next.js, TypeScript, Tailwind CSS and shadcn/ui components, an Embla carousel, light and dark themes.', 'A complete magazine site and a document that explains the UX choices.', 'Ordering a lot of content on a single home page without overloading it.'),
  ('2ieapp', '2ieApp: a website with a members'' area', 'Next.js site with home, about and contact pages, sign-up and sign-in.', 'A multi-page Next.js site with a public area (home, about, contact) and an authentication area (sign-up, sign-in) that share their layouts.', 'A course project to get to grips with Next.js and its routing.', 'Next.js (App Router) with route groups to separate authentication from the public pages, reusable components and Tailwind CSS.', 'A responsive multi-page site with sign-up and sign-in flows.', 'Organising the routes and the layouts shared between the two areas.'),
  ('medicare-portail-patient', 'MediCare: a patient portal', 'Patient portal interface: appointments, medical record and health tips.', 'The Next.js interface of a portal where patients see their appointments, access their medical record and receive health tips.', 'Bringing together in one place the information a patient needs between two appointments.', 'Next.js and TypeScript, Tailwind CSS and shadcn/ui, dedicated components (appointment cards, filter tabs, health tips).', 'A clear, responsive interface, ready to connect to a backend.', 'Presenting medical information in a reassuring, readable way.'),
  ('baobab-rising', 'Baobab Rising: a website for a speech', 'Bilingual showcase site for the ''Baobab Rising'' speech on African youth, with its video.', 'A site in French and English that presents the speech ''Baobab Rising: nurturing the future through African youth'', with the video and the key messages.', 'Giving an online home to a talk about African youth.', 'React, TypeScript and Vite, Tailwind CSS, bilingual content and a video player.', 'A showcase site in two languages, easy to share.', 'Carrying a strong message with a restrained layout, in two languages.'),
  ('togoporc', 'TogoPorc: a showcase site for a pig farm in Togo', 'My first website: an online showcase for selling farm-raised pigs in Togo.', 'A static site that presents what a pig farm in Togo offers: breeds suited to the local climate, selection for rearing and breeding, and a way to get in touch.', 'A local farm wanted to be visible online and present its animals.', 'HTML, CSS and JavaScript, with no framework.', 'A responsive online showcase, my first web project.', 'Learning the basics of web development and responsive layout.')
) AS t(slug, title_en, short_description_en, full_description_en, context_en, approach_en, results_en, challenges_en)
WHERE projects.slug = t.slug;

UPDATE skill_categories SET name_en = t.name_en
FROM (VALUES
  ('Langages', 'Languages'),
  ('Langages de programmation', 'Programming languages'),
  ('Analyse de données', 'Data analysis'),
  ('Visualisation de données', 'Data visualisation'),
  ('Bases de données', 'Databases'),
  ('Outils', 'Tools'),
  ('Intelligence artificielle', 'Artificial intelligence'),
  ('IA générative', 'Generative AI'),
  ('Développement web', 'Web development')
) AS t(name, name_en)
WHERE skill_categories.name = t.name AND COALESCE(skill_categories.name_en, '') = '';

COMMIT;
